const FILES = {"src/lib/platform-fee.ts":"// TrustLoop's own income: a small percentage taken when a freelancer withdraws.\n// Set WITHDRAWAL_FEE_PERCENT in the environment to change it (default 2, allowed 0 to 20).\nexport function withdrawalFeePercent(): number {\n  const n = Number(process.env.WITHDRAWAL_FEE_PERCENT ?? \"2\");\n  return Number.isFinite(n) ? Math.min(20, Math.max(0, n)) : 2;\n}\n\n// The fee is rounded to the nearest naira. \"net\" is what the user actually receives.\nexport function withdrawalFee(amountNgn: number) {\n  const percent = withdrawalFeePercent();\n  const fee = Math.round((amountNgn * percent) / 100);\n  return { percent, fee, net: amountNgn - fee };\n}\n","src/app/actions/withdraw.ts":"\"use server\";\n\nimport { randomBytes } from \"crypto\";\nimport { redirect } from \"next/navigation\";\nimport { db } from \"@/lib/db\";\nimport { getUserId } from \"@/lib/session\";\nimport { getBalance } from \"@/lib/money\";\nimport { notify } from \"@/lib/notify\";\nimport { payments } from \"@/lib/payments\";\nimport { lookupCustomer } from \"@/lib/payments/customers\";\nimport { withdrawalFee } from \"@/lib/platform-fee\";\n\nconst ASSETS: Record<string, string[]> = { USDC: [\"BASE\"], USDT: [\"TRC20\", \"BEP20\"] };\n\nexport async function requestWithdrawal(_prev: string | null, formData: FormData) {\n  const userId = await getUserId();\n  if (!userId) redirect(\"/login\");\n\n  const amountNgn = Number(formData.get(\"amountNgn\"));\n  const asset = String(formData.get(\"asset\") ?? \"\");\n  const network = String(formData.get(\"network\") ?? \"\");\n  const address = String(formData.get(\"address\") ?? \"\").trim();\n\n  if (!ASSETS[asset]?.includes(network)) return \"Choose a supported asset and network.\";\n  if (!Number.isInteger(amountNgn) || amountNgn < 100) return \"Enter a whole amount of at least ₦100.\";\n  if (!/^[A-Za-z0-9]{26,64}$/.test(address)) return \"Enter a valid wallet address.\";\n\n  // With live Roqqu, an account Roqqu has blacklisted cannot withdraw.\n  const me = await db.user.findUnique({ where: { id: userId }, select: { email: true } });\n  if (me) {\n    const customer = await lookupCustomer(me.email);\n    if (customer?.blacklisted) return \"Withdrawals are paused for your account. Please contact support.\";\n  }\n\n  // TrustLoop keeps a small fee. The user is debited the full amount and receives the rest.\n  const { percent, fee, net } = withdrawalFee(amountNgn);\n  if (net < 50) return \"That amount is too small after the fee. Try a larger amount.\";\n\n  const reference = \"TL\" + randomBytes(7).toString(\"hex\");\n  try {\n    await db.$transaction(\n      async (tx) => {\n        const { balance } = await getBalance(tx, userId);\n        if (amountNgn > balance) throw new Error(\"INSUFFICIENT\");\n        await tx.withdrawal.create({ data: { userId, amountNgn, asset, network, address, reference, feeNgn: fee, feePercent: percent } });\n        await tx.ledgerEntry.create({\n          data: { userId, type: \"WITHDRAWAL\", amountNgn: -amountNgn, reference, note: `${asset} on ${network}${fee ? ` (fee ₦${fee.toLocaleString(\"en-NG\")})` : \"\"}` },\n        });\n      },\n      { isolationLevel: \"Serializable\" },\n    );\n  } catch (e) {\n    if (e instanceof Error && e.message === \"INSUFFICIENT\") return \"That is more than your available balance.\";\n    return \"Could not start the withdrawal. Please try again.\";\n  }\n\n  try {\n    const res = await payments.sendPayout({\n      reference,\n      amountNgn: net, // the fee stays with TrustLoop, so only the rest is sent\n      toAddress: address,\n      network: network.toLowerCase(),\n      token: asset.toLowerCase(),\n    });\n    if (res.txHash) {\n      // The simulator finishes at once.\n      await db.withdrawal.update({ where: { reference }, data: { status: \"COMPLETED\", txHash: res.txHash } });\n      await notify(db, userId, \"Withdrawal sent\", `₦${net.toLocaleString(\"en-NG\")} was sent as ${asset} on ${network}.`, \"/dashboard\");\n    } else if (res.refid) {\n      // Roqqu queued it. The \"token_sent\" webhook (or a status check) completes it.\n      await db.withdrawal.update({ where: { reference }, data: { status: \"PROCESSING\", refid: res.refid } });\n    }\n  } catch {\n    // The transfer failed, so put the money back in the wallet.\n    await db.$transaction([\n      db.withdrawal.update({ where: { reference }, data: { status: \"FAILED\" } }),\n      db.ledgerEntry.create({\n        data: { userId, type: \"REFUND\", amountNgn, reference: `${reference}_rev`, note: \"Withdrawal reversed\" },\n      }),\n    ]);\n    return \"The transfer failed and your balance was not charged. Please try again.\";\n  }\n  redirect(\"/wallet?m=withdrawn\");\n}\n","src/components/WithdrawForm.tsx":"import WithdrawFormClient from \"./WithdrawFormClient\";\nimport { withdrawalFeePercent } from \"@/lib/platform-fee\";\n\n// The fee percentage is read on the server and passed down, so the form always shows the real rate.\nexport default function WithdrawForm({ balance }: { balance: number }) {\n  return <WithdrawFormClient balance={balance} feePercent={withdrawalFeePercent()} />;\n}\n","src/components/WithdrawFormClient.tsx":"\"use client\";\n\nimport { useActionState, useState } from \"react\";\nimport { requestWithdrawal } from \"@/app/actions/withdraw\";\n\nconst NETWORKS: Record<string, string[]> = { USDT: [\"TRC20\", \"BEP20\"], USDC: [\"BASE\"] };\nconst naira = (n: number) => \"₦\" + n.toLocaleString(\"en-NG\");\nconst field = \"w-full rounded-xl border border-ink/15 bg-white px-4 py-3 text-base outline-none focus:border-forest\";\n\nexport default function WithdrawFormClient({ balance, feePercent }: { balance: number; feePercent: number }) {\n  const [error, action, pending] = useActionState(requestWithdrawal, null);\n  const [asset, setAsset] = useState(\"USDT\");\n  const [amount, setAmount] = useState(\"\");\n  const n = Math.floor(Number(amount)) || 0;\n  const fee = Math.round((n * feePercent) / 100);\n  const net = n - fee;\n\n  return (\n    <form action={action} className=\"space-y-3\">\n      <p className=\"text-sm text-muted\">Available: <b className=\"text-ink\">{naira(balance)}</b></p>\n      <div>\n        <label htmlFor=\"amountNgn\" className=\"mb-1 block text-sm font-semibold\">Amount in naira</label>\n        <input id=\"amountNgn\" name=\"amountNgn\" type=\"number\" min={100} step={1} max={balance} required inputMode=\"numeric\"\n          value={amount} onChange={(e) => setAmount(e.target.value)} className={field} placeholder=\"e.g. 5000\" />\n      </div>\n\n      <div className=\"rounded-xl bg-cream px-4 py-3 text-sm\" aria-live=\"polite\">\n        {feePercent > 0 ? (\n          <>\n            <p className=\"font-semibold\">TrustLoop charges {feePercent}% when you withdraw.</p>\n            {n >= 100 ? (\n              <p className=\"mt-1 text-muted\">Fee {naira(fee)}. You receive <b className=\"text-ink\">{naira(net)}</b> as {asset}.</p>\n            ) : (\n              <p className=\"mt-1 text-muted\">Enter an amount to see exactly what you will receive.</p>\n            )}\n          </>\n        ) : (\n          <p className=\"font-semibold\">There is no withdrawal fee right now.</p>\n        )}\n      </div>\n\n      <div className=\"grid grid-cols-2 gap-3\">\n        <div>\n          <label htmlFor=\"asset\" className=\"mb-1 block text-sm font-semibold\">Asset</label>\n          <select id=\"asset\" name=\"asset\" value={asset} onChange={(e) => setAsset(e.target.value)} className={field}>\n            {Object.keys(NETWORKS).map((a) => <option key={a}>{a}</option>)}\n          </select>\n        </div>\n        <div>\n          <label htmlFor=\"network\" className=\"mb-1 block text-sm font-semibold\">Network</label>\n          <select id=\"network\" name=\"network\" key={asset} className={field}>\n            {NETWORKS[asset].map((x) => <option key={x}>{x}</option>)}\n          </select>\n        </div>\n      </div>\n      <div>\n        <label htmlFor=\"address\" className=\"mb-1 block text-sm font-semibold\">Your wallet address</label>\n        <input id=\"address\" name=\"address\" required minLength={26} maxLength={64} autoComplete=\"off\" spellCheck={false} className={`${field} font-mono text-sm`} placeholder=\"Paste the address that receives the money\" />\n      </div>\n      {error && <p role=\"alert\" className=\"rounded-xl bg-red-50 px-4 py-3 text-sm font-semibold text-red-700\">{error}</p>}\n      <button disabled={pending} className=\"w-full rounded-xl bg-forest px-5 py-3 font-bold text-white disabled:opacity-60\">\n        {pending ? \"Sending...\" : \"Withdraw\"}\n      </button>\n    </form>\n  );\n}\n","src/lib/payments/roqqu-events.ts":"import { Prisma } from \"@prisma/client\";\nimport { db } from \"@/lib/db\";\nimport { notify } from \"@/lib/notify\";\nimport { asRecord, isProdKey } from \"./client\";\nimport { getNgnPerUsdt } from \"./rates\";\n\n// Turns a decrypted Roqqu webhook into changes in our database.\n// Every event is applied once: the event id is stored first, and a repeat is ignored.\nexport type EventResult = \"ok\" | \"duplicate\" | \"ignored\";\n\ntype RoqquEvent = { event_id?: unknown; event_type?: unknown; meta_data?: unknown; datetime?: unknown };\n\nclass Ignored extends Error {}\ntype Tx = Prisma.TransactionClient;\n\nconst naira = (n: number) => \"₦\" + n.toLocaleString(\"en-NG\");\nconst str = (v: unknown) => (v === undefined || v === null ? \"\" : String(v));\nconst num = (v: unknown) => {\n  const n = Number(v);\n  return Number.isFinite(n) ? n : null;\n};\n\nexport async function processRoqquEvent(evt: RoqquEvent): Promise<EventResult> {\n  const eventId = str(evt.event_id);\n  const type = str(evt.event_type);\n  const meta = asRecord(evt.meta_data);\n  if (!eventId || !type) return \"ignored\";\n\n  // Only the USDT-to-naira price needs a network call, so do it before the transaction.\n  const rate = type === \"token_received\" ? (await getNgnPerUsdt()).rate : 0;\n\n  try {\n    await db.$transaction(async (tx) => {\n      await tx.webhookEvent.create({ data: { eventId, type: `roqqu_${type}` } });\n      switch (type) {\n        case \"payment_link_completed\":\n          return paymentLink(tx, meta, false);\n        case \"payment_link_completed_overpaid\":\n          return paymentLink(tx, meta, true);\n        case \"payment_link_failed\":\n          return paymentLinkFailed(tx, meta);\n        case \"token_received\":\n          return tokenReceived(tx, meta, rate);\n        case \"token_sent\":\n          return tokenSent(tx, meta);\n        case \"token_refunded\":\n          return tokenRefunded(tx, meta);\n        default:\n          throw new Ignored(); // not an event we use\n      }\n    });\n    return \"ok\";\n  } catch (e) {\n    if (e instanceof Ignored) return \"ignored\";\n    if (e instanceof Prisma.PrismaClientKnownRequestError && e.code === \"P2002\") return \"duplicate\";\n    throw e;\n  }\n}\n\nfunction log(tx: Tx, data: { kind: string; userId?: string | null; reference?: string; hash?: string; token?: string; network?: string; value?: number | null; amountNgn?: number | null; status: string; note?: string }) {\n  return tx.roqquTx.create({\n    data: {\n      kind: data.kind,\n      live: isProdKey(),\n      userId: data.userId ?? null,\n      reference: data.reference || null,\n      hash: data.hash || null,\n      token: data.token ? data.token.toLowerCase() : null,\n      network: data.network ? data.network.toLowerCase() : null,\n      value: data.value ?? null,\n      amountNgn: data.amountNgn ?? null,\n      status: data.status,\n      note: data.note ?? null,\n    },\n  });\n}\n\n// A hirer paid a Roqqu payment link. The payment_reference is the reference we created.\nasync function findDeposit(tx: Tx, meta: Record<string, unknown>) {\n  const refs = [str(meta.payment_reference), str(asRecord(meta.metadata).reference)].filter(Boolean);\n  if (refs.length === 0) throw new Ignored();\n  const dep = await tx.deposit.findFirst({ where: { reference: { in: refs } } });\n  if (!dep) throw new Ignored();\n  return dep;\n}\n\nasync function paymentLink(tx: Tx, meta: Record<string, unknown>, overpaid: boolean) {\n  const dep = await findDeposit(tx, meta);\n  if (dep.status === \"CONFIRMED\") return;\n  const hash = str(meta.hash);\n  const network = str(meta.network).toLowerCase();\n  const token = str(meta.token).toLowerCase();\n  await tx.deposit.update({ where: { id: dep.id }, data: { status: \"CONFIRMED\", txHash: hash || null, network: network || null, token: token || null } });\n  // Same reference the simulator uses, so one payment can never be credited twice.\n  await tx.ledgerEntry.create({\n    data: { userId: dep.userId, type: \"DEPOSIT\", amountNgn: dep.amountNgn, reference: `DEP_${dep.reference}`, note: \"Wallet top-up\" },\n  });\n  await log(tx, {\n    kind: \"PAYMENT_LINK\",\n    userId: dep.userId,\n    reference: dep.reference,\n    hash,\n    token,\n    network,\n    value: num(meta.value),\n    amountNgn: dep.amountNgn,\n    status: overpaid ? \"OVERPAID\" : \"COMPLETED\",\n    note: overpaid ? `Overpaid by ${str(meta.overpaid_amount)} ${token}` : undefined,\n  });\n  await notify(\n    tx,\n    dep.userId,\n    \"Money added\",\n    overpaid\n      ? `${naira(dep.amountNgn)} was added to your wallet. You paid a little extra, so please contact support if you want the difference back.`\n      : `${naira(dep.amountNgn)} was added to your wallet.`,\n    \"/wallet\",\n  );\n}\n\n// The customer paid too little (or the payment failed). Nothing is credited.\nasync function paymentLinkFailed(tx: Tx, meta: Record<string, unknown>) {\n  const dep = await findDeposit(tx, meta);\n  if (dep.status !== \"PENDING\") return;\n  await tx.deposit.update({ where: { id: dep.id }, data: { status: \"FAILED\", txHash: str(meta.hash) || null } });\n  await log(tx, {\n    kind: \"PAYMENT_LINK\",\n    userId: dep.userId,\n    reference: dep.reference,\n    hash: str(meta.hash),\n    token: str(meta.token),\n    network: str(meta.network),\n    value: num(meta.value),\n    amountNgn: dep.amountNgn,\n    status: \"FAILED\",\n    note: `Underpaid by ${str(meta.underpaid_amount)} ${str(meta.token).toLowerCase()}`,\n  });\n  await notify(tx, dep.userId, \"Payment not completed\", \"Your payment did not reach the full amount, so nothing was added. Please try again.\", \"/wallet\");\n}\n\n// USDT arrived at a user's own Roqqu address (not through a payment link).\nasync function tokenReceived(tx: Tx, meta: Record<string, unknown>, rate: number) {\n  const token = str(meta.token).toLowerCase();\n  const status = str(meta.status).toLowerCase();\n  const hash = str(meta.hash);\n  const address = str(meta.address);\n  if (token !== \"usdt\" || !hash || !address || (status && status !== \"confirmed\")) throw new Ignored();\n\n  const row = await tx.depositAddress.findFirst({ where: { address } });\n  const userId = row?.userId ?? (await tx.user.findFirst({ where: { depositAddress: address }, select: { id: true } }))?.id;\n  if (!userId) throw new Ignored();\n\n  const value = num(meta.value);\n  const amountNgn = value && rate ? Math.floor(value * rate) : 0;\n  if (amountNgn < 1) throw new Ignored();\n\n  await tx.ledgerEntry.create({\n    data: { userId, type: \"DEPOSIT\", amountNgn, reference: `CH_${hash}`, note: `USDT received (${str(meta.network).toUpperCase()})` },\n  });\n  await log(tx, { kind: \"CHAIN_DEPOSIT\", userId, reference: address, hash, token, network: str(meta.network), value, amountNgn, status: \"CONFIRMED\" });\n  await notify(tx, userId, \"Money added\", `${value} USDT arrived at your wallet address. ${naira(amountNgn)} was added to your balance.`, \"/wallet\");\n}\n\n// A withdrawal left Roqqu and has an on-chain hash.\nasync function tokenSent(tx: Tx, meta: Record<string, unknown>) {\n  const refid = str(meta.reference);\n  if (!refid) throw new Ignored();\n  const w = await tx.withdrawal.findFirst({ where: { refid } });\n  if (!w) throw new Ignored();\n  const hash = str(meta.hash);\n  if (w.status !== \"COMPLETED\") {\n    await tx.withdrawal.update({ where: { id: w.id }, data: { status: \"COMPLETED\", txHash: hash || w.txHash } });\n    await notify(tx, w.userId, \"Withdrawal sent\", `${naira(w.amountNgn - w.feeNgn)} was sent as ${w.asset} on ${w.network}.`, \"/wallet\");\n  }\n  await log(tx, { kind: \"SEND\", userId: w.userId, reference: w.reference, hash, token: str(meta.token), network: str(meta.network), value: num(meta.value), amountNgn: w.amountNgn, status: \"SENT\" });\n}\n\n// A send failed and Roqqu refunded it, so the money goes back to the user's wallet.\nasync function tokenRefunded(tx: Tx, meta: Record<string, unknown>) {\n  const refid = str(meta.refid);\n  if (!refid) throw new Ignored();\n  const w = await tx.withdrawal.findFirst({ where: { refid } });\n  if (!w) throw new Ignored();\n  if (w.status === \"FAILED\") return;\n  await tx.withdrawal.update({ where: { id: w.id }, data: { status: \"FAILED\" } });\n  await tx.ledgerEntry.create({\n    data: { userId: w.userId, type: \"REFUND\", amountNgn: w.amountNgn, reference: `${w.reference}_rev`, note: \"Withdrawal refunded\" },\n  });\n  await log(tx, { kind: \"REFUND\", userId: w.userId, reference: w.reference, hash: str(meta.hash), token: str(meta.token), network: str(meta.network), value: num(meta.value), amountNgn: w.amountNgn, status: \"REFUNDED\" });\n  await notify(tx, w.userId, \"Withdrawal returned\", `${naira(w.amountNgn)} was returned to your wallet because the transfer did not go through.`, \"/wallet\");\n}\n","src/app/actions/roqqu.ts":"\"use server\";\n\nimport { redirect } from \"next/navigation\";\nimport { db } from \"@/lib/db\";\nimport { getUserId } from \"@/lib/session\";\nimport { notify } from \"@/lib/notify\";\nimport { ensureDepositAddress, NETWORKS, type DepositNetwork } from \"@/lib/wallet\";\nimport { isLiveMode, roqquRequest, asRecord } from \"@/lib/payments/client\";\nimport { refreshRoqquStatus } from \"@/lib/payments/customers\";\n\nasync function requireUser() {\n  const userId = await getUserId();\n  if (!userId) redirect(\"/login\");\n  return userId;\n}\n\n// Messages for the wallet page are fixed codes, never text from a URL.\nconst back = (code: string): never => redirect(`/wallet?m=${code}`);\n\nexport async function createAddress(network: string) {\n  const userId = await requireUser();\n  if (!(NETWORKS as readonly string[]).includes(network)) return back(\"badnet\");\n  await ensureDepositAddress(userId, network as DepositNetwork);\n  return back(\"address\");\n}\n\nexport async function checkMyRoqquStatus() {\n  const userId = await requireUser();\n  const status = await refreshRoqquStatus(userId);\n  return back(status === \"sandbox\" ? \"sandbox\" : status === \"unknown\" ? \"unreachable\" : `status_${status}`);\n}\n\n// Asks Roqqu where a withdrawal is (GET /transaction/refId/:refid).\nexport async function checkWithdrawal(reference: string) {\n  const userId = await requireUser();\n  const w = await db.withdrawal.findUnique({ where: { reference } });\n  if (!w || w.userId !== userId) return back(\"nowd\");\n  if (!w.refid || !isLiveMode()) return back(\"nosend\");\n  let data: Record<string, unknown>;\n  try {\n    data = asRecord(await roqquRequest(\"GET\", `/transaction/refId/${encodeURIComponent(w.refid)}`));\n  } catch {\n    return back(\"unreachable\");\n  }\n  const hash = data.tx_hash ? String(data.tx_hash) : \"\";\n  if (!hash) return back(\"pending\");\n  if (w.status !== \"COMPLETED\") {\n    await db.withdrawal.update({ where: { id: w.id }, data: { status: \"COMPLETED\", txHash: hash } });\n    await notify(db, userId, \"Withdrawal sent\", `₦${(w.amountNgn - w.feeNgn).toLocaleString(\"en-NG\")} was sent as ${w.asset} on ${w.network}.`, \"/wallet\");\n  }\n  return back(\"confirmed\");\n}\n\n// Asks Roqqu to refund a send that never went through (POST /transaction/refund).\n// Roqqu only allows this an hour after the send, and only if it failed on-chain.\n// The money comes back to the wallet when Roqqu's \"token_refunded\" webhook arrives.\nexport async function recoverWithdrawal(reference: string) {\n  const userId = await requireUser();\n  const w = await db.withdrawal.findUnique({ where: { reference } });\n  if (!w || w.userId !== userId || !w.refid || !isLiveMode()) return back(\"nosend\");\n  if (w.status !== \"PROCESSING\" || w.txHash) return back(\"notstuck\");\n  if (Date.now() - w.createdAt.getTime() < 60 * 60 * 1000) return back(\"toosoon\");\n  try {\n    await roqquRequest(\"POST\", \"/transaction/refund\", { form: { refid: w.refid } });\n  } catch {\n    return back(\"refund_denied\");\n  }\n  await db.withdrawal.update({ where: { id: w.id }, data: { status: \"REFUND_REQUESTED\" } });\n  return back(\"refund_ok\");\n}\n","src/app/wallet/page.tsx":"import { Suspense } from \"react\";\nimport Link from \"next/link\";\nimport { redirect } from \"next/navigation\";\nimport { ArrowLeft, ArrowDownLeft, ArrowUpRight, Lock, Wallet, ShieldCheck, ExternalLink, RefreshCw, Gauge } from \"lucide-react\";\nimport { db } from \"@/lib/db\";\nimport { getUserId } from \"@/lib/session\";\nimport { getBalance } from \"@/lib/money\";\nimport AddMoneyForm from \"@/components/AddMoneyForm\";\nimport CopyButton from \"@/components/CopyButton\";\nimport { createAddress, checkMyRoqquStatus, checkWithdrawal, recoverWithdrawal } from \"@/app/actions/roqqu\";\nimport { listDepositAddresses, NETWORKS } from \"@/lib/wallet\";\nimport { getNgnPerUsdt } from \"@/lib/payments/rates\";\nimport { getSendFee } from \"@/lib/payments/fees\";\nimport { isLiveMode } from \"@/lib/payments/client\";\nimport { explorerUrl } from \"@/lib/proof\";\nimport WithdrawForm from \"@/components/WithdrawForm\";\nimport { withdrawalFeePercent } from \"@/lib/platform-fee\";\n\nconst naira = (n: number) => \"₦\" + n.toLocaleString(\"en-NG\");\nconst LABEL: Record<string, string> = {\n  DEPOSIT: \"Money added\",\n  TASK_FUND: \"Locked for a task\",\n  TASK_PAYOUT: \"Task payment received\",\n  WITHDRAWAL: \"Withdrawal\",\n  REFUND: \"Withdrawal returned\",\n};\nconst W_STATUS: Record<string, [string, string]> = {\n  PENDING: [\"Starting\", \"bg-cream text-muted\"],\n  PROCESSING: [\"Sending\", \"bg-amber-50 text-amber-800\"],\n  COMPLETED: [\"Sent\", \"bg-emerald-100 text-emerald-800\"],\n  FAILED: [\"Returned to wallet\", \"bg-cream text-muted\"],\n  REFUND_REQUESTED: [\"Refund requested\", \"bg-amber-50 text-amber-800\"],\n};\nconst MESSAGES: Record<string, [boolean, string]> = {\n  withdrawn: [true, \"Withdrawal started. You will be notified when it is sent.\"],\n  address: [true, \"Your address is ready.\"],\n  badnet: [false, \"That network is not supported.\"],\n  sandbox: [true, \"Sandbox mode: there is no Roqqu account to check yet.\"],\n  unreachable: [false, \"Could not reach Roqqu just now. Please try again in a moment.\"],\n  status_verified: [true, \"Your Roqqu account is verified. A badge now shows on your Trust Passport.\"],\n  status_unverified: [true, \"Your Roqqu account exists but is not verified yet.\"],\n  status_not_found: [false, \"Roqqu has no account for this email yet.\"],\n  status_blacklisted: [false, \"Roqqu has blocked this account. Please contact support.\"],\n  nosend: [false, \"This withdrawal cannot be checked.\"],\n  nowd: [false, \"Withdrawal not found.\"],\n  pending: [true, \"Roqqu has not put this transfer on the blockchain yet. Check again shortly.\"],\n  confirmed: [true, \"Confirmed. The transfer is on the blockchain.\"],\n  notstuck: [false, \"This withdrawal is not stuck.\"],\n  toosoon: [false, \"Roqqu only allows a refund an hour after the transfer was started.\"],\n  refund_denied: [false, \"Roqqu did not accept the refund yet. It only refunds transfers that failed on the blockchain.\"],\n  refund_ok: [true, \"Refund requested. Your balance will be restored when Roqqu confirms it.\"],\n};\n\ntype Search = Promise<{ need?: string; task?: string; added?: string; m?: string }>;\n\nexport default function WalletPage({ searchParams }: { searchParams: Search }) {\n  return (\n    <Suspense fallback={<div className=\"p-10 text-sm text-muted\">Loading your wallet...</div>}>\n      <WalletInner searchParams={searchParams} />\n    </Suspense>\n  );\n}\n\nasync function WalletInner({ searchParams }: { searchParams: Search }) {\n  const sp = await searchParams;\n  const userId = await getUserId();\n  if (!userId) redirect(\"/login\");\n  const user = await db.user.findUnique({ where: { id: userId } });\n  if (!user) redirect(\"/login\");\n\n  const [bal, entries, addresses, withdrawals, rate, fee] = await Promise.all([\n    getBalance(db, userId),\n    db.ledgerEntry.findMany({ where: { userId }, orderBy: { createdAt: \"desc\" }, take: 15 }),\n    listDepositAddresses(userId),\n    db.withdrawal.findMany({ where: { userId }, orderBy: { createdAt: \"desc\" }, take: 6 }),\n    getNgnPerUsdt(),\n    getSendFee(),\n  ]);\n  const sandbox = process.env.ROQQU_ENV !== \"live\";\n  const live = isLiveMode();\n  const need = Math.max(100, Number(sp.need) || 0);\n  const note = sp.m ? MESSAGES[sp.m] : undefined;\n  const statusText: Record<string, string> = {\n    verified: \"Verified on Roqqu\",\n    unverified: \"On Roqqu, not verified yet\",\n    not_found: \"Not found on Roqqu\",\n    blacklisted: \"Blocked by Roqqu\",\n  };\n\n  return (\n    <main className=\"mx-auto max-w-3xl space-y-5 px-5 py-6\">\n      <Link href=\"/dashboard\" className=\"inline-flex items-center gap-1 text-sm font-semibold text-muted hover:text-ink\">\n        <ArrowLeft className=\"h-4 w-4\" aria-hidden /> Dashboard\n      </Link>\n\n      {sp.added && (\n        <p role=\"status\" className=\"rounded-xl bg-emerald-100 px-4 py-3 text-sm font-semibold text-emerald-800\">\n          Payment received. Your wallet will update as soon as Roqqu confirms it.\n        </p>\n      )}\n      {note && (\n        <p role=\"status\" className={`rounded-xl px-4 py-3 text-sm font-semibold ${note[0] ? \"bg-emerald-100 text-emerald-800\" : \"bg-amber-50 text-amber-800\"}`}>\n          {note[1]}\n        </p>\n      )}\n      {sp.need && (\n        <p role=\"status\" className=\"rounded-xl bg-amber-50 px-4 py-3 text-sm font-semibold text-amber-800\">\n          Your wallet is {naira(Number(sp.need) || 0)} short for that task. Add money, then fund the task again.\n        </p>\n      )}\n\n      <section className=\"rounded-3xl bg-forest p-6 text-white\">\n        <p className=\"flex items-center gap-2 text-sm font-semibold text-white/80\">\n          <Wallet className=\"h-4 w-4\" aria-hidden /> Wallet balance\n        </p>\n        <p className=\"mt-2 text-4xl font-extrabold\">{naira(bal.balance)}</p>\n        <div className=\"mt-5 grid grid-cols-3 gap-3 text-sm\">\n          <div><p className=\"text-white/70\">Added</p><p className=\"font-bold\">{naira(bal.deposited)}</p></div>\n          <div><p className=\"text-white/70\">Earned</p><p className=\"font-bold\">{naira(bal.earned)}</p></div>\n          <div><p className=\"text-white/70\">Locked in tasks</p><p className=\"font-bold\">{naira(bal.funded)}</p></div>\n        </div>\n      </section>\n\n      <div className=\"grid gap-5 md:grid-cols-2\">\n        <section className=\"rounded-2xl border border-ink/10 bg-white p-5 shadow-sm shadow-ink/5\">\n          <h2 className=\"text-lg font-bold\">Add money</h2>\n          <p className=\"mt-1 text-sm text-muted\">\n            Top up your wallet, then fund tasks from it.{\" \"}\n            {sandbox ? \"Sandbox: a simulator stands in for the Roqqu payment page.\" : \"You pay on Roqqu's secure payment page and can choose Bitcoin or USDT.\"}\n          </p>\n          <div className=\"mt-4\">\n            <AddMoneyForm defaultAmount={need} sandbox={sandbox} />\n          </div>\n        </section>\n\n        <section className=\"rounded-2xl border border-ink/10 bg-white p-5 shadow-sm shadow-ink/5\">\n          <h2 className=\"text-lg font-bold\">Your Roqqu wallet addresses</h2>\n          <p className=\"mt-1 text-sm text-muted\">\n            Send USDT to one of these from any wallet and your balance goes up by itself.\n          </p>\n          <div className=\"mt-3 space-y-3\">\n            {NETWORKS.map((n) => {\n              const a = addresses.find((x) => x.network === n);\n              return (\n                <div key={n}>\n                  <p className=\"text-xs font-bold uppercase tracking-wide text-muted\">USDT on {n.toUpperCase()}</p>\n                  {a ? (\n                    <>\n                      <p className=\"mt-1 break-all rounded-xl bg-cream px-3 py-2 font-mono text-xs\">{a.address}</p>\n                      <div className=\"mt-2 flex flex-wrap items-center gap-3\">\n                        <CopyButton text={a.address} />\n                        {a.sandbox && <span className=\"text-xs text-muted\">Simulated sandbox address. It exists on no real network.</span>}\n                      </div>\n                    </>\n                  ) : (\n                    <form action={createAddress.bind(null, n)} className=\"mt-1\">\n                      <button className=\"rounded-xl border border-ink/15 px-4 py-2 text-sm font-semibold hover:bg-cream\">Create {n.toUpperCase()} address</button>\n                    </form>\n                  )}\n                </div>\n              );\n            })}\n          </div>\n        </section>\n      </div>\n\n      <section className=\"rounded-2xl border border-ink/10 bg-white p-5 shadow-sm shadow-ink/5\">\n        <h2 className=\"flex items-center gap-2 text-lg font-bold\"><Gauge className=\"h-5 w-5 text-forest\" aria-hidden /> Rate, fees and your Roqqu account</h2>\n        <dl className=\"mt-3 grid gap-4 text-sm sm:grid-cols-2\">\n          <div>\n            <dt className=\"text-muted\">Price of 1 USDT</dt>\n            <dd className=\"font-bold\">{naira(Math.round(rate.rate))}</dd>\n            <dd className=\"text-xs text-muted\">{rate.source === \"roqqu\" ? \"Live rate from Roqqu\" : live ? \"Roqqu rate unavailable, using the set rate\" : \"Fixed sandbox rate\"}</dd>\n          </div>\n          <div>\n            <dt className=\"text-muted\">TrustLoop withdrawal fee</dt>\n            <dd className=\"font-bold\">{withdrawalFeePercent() > 0 ? `${withdrawalFeePercent()}%` : \"None right now\"}</dd>\n            <dd className=\"text-xs text-muted\">Shown again before you confirm. Joining and earning are free.</dd>\n          </div>\n          <div>\n            <dt className=\"text-muted\">Roqqu network fee</dt>\n            <dd className=\"font-bold\">{fee?.percentage != null ? `${fee.percentage}%` : fee?.fee != null ? `${fee.fee} USDT` : \"Shown once live\"}</dd>\n            <dd className=\"text-xs text-muted\">Charged by Roqqu when the transfer is sent</dd>\n          </div>\n          <div>\n            <dt className=\"text-muted\">Roqqu account</dt>\n            <dd className=\"flex items-center gap-1 font-bold\"><ShieldCheck className=\"h-4 w-4 text-forest\" aria-hidden />{user.roqquStatus ? statusText[user.roqquStatus] ?? \"Checked\" : \"Not checked\"}</dd>\n            <dd>\n              <form action={checkMyRoqquStatus}>\n                <button className=\"mt-1 inline-flex items-center gap-1 text-xs font-semibold text-forest underline\"><RefreshCw className=\"h-3 w-3\" aria-hidden /> Check now</button>\n              </form>\n            </dd>\n          </div>\n        </dl>\n      </section>\n\n      <section className=\"rounded-2xl border border-ink/10 bg-white p-5 shadow-sm shadow-ink/5\">\n        <h2 className=\"text-lg font-bold\">Withdraw to your own wallet</h2>\n        <div className=\"mt-3\">\n          <WithdrawForm balance={bal.balance} />\n        </div>\n      </section>\n\n      {withdrawals.length > 0 && (\n        <section className=\"rounded-2xl border border-ink/10 bg-white p-5 shadow-sm shadow-ink/5\">\n          <h2 className=\"text-lg font-bold\">Withdrawals</h2>\n          <ul className=\"mt-3 divide-y divide-ink/10\">\n            {withdrawals.map((w) => {\n              const [label, tone] = W_STATUS[w.status] ?? [w.status, \"bg-cream text-muted\"];\n              const url = explorerUrl(w.network, w.txHash);\n              const old = Date.now() - w.createdAt.getTime() > 60 * 60 * 1000;\n              return (\n                <li key={w.id} className=\"space-y-2 py-3 text-sm\">\n                  <div className=\"flex items-center justify-between gap-3\">\n                    <span className=\"font-semibold\">{naira(w.amountNgn)} · {w.asset} on {w.network}{w.feeNgn > 0 && <span className=\"font-normal text-muted\"> (fee {naira(w.feeNgn)})</span>}</span>\n                    <span className={`rounded-full px-3 py-1 text-xs font-bold ${tone}`}>{label}</span>\n                  </div>\n                  {w.txHash && (\n                    <p className=\"break-all text-xs text-muted\">\n                      {w.txHash.startsWith(\"mock_\") ? \"Sandbox transfer (no blockchain record)\" : w.txHash}\n                      {url && (\n                        <a href={url} target=\"_blank\" rel=\"noopener noreferrer\" className=\"ml-2 inline-flex items-center gap-1 font-semibold text-forest underline\">\n                          View <ExternalLink className=\"h-3 w-3\" aria-hidden />\n                        </a>\n                      )}\n                    </p>\n                  )}\n                  {w.status === \"PROCESSING\" && w.refid && (\n                    <div className=\"flex flex-wrap gap-3\">\n                      <form action={checkWithdrawal.bind(null, w.reference)}>\n                        <button className=\"rounded-lg border border-ink/15 px-3 py-1.5 text-xs font-semibold hover:bg-cream\">Check status</button>\n                      </form>\n                      {old && (\n                        <form action={recoverWithdrawal.bind(null, w.reference)}>\n                          <button className=\"rounded-lg border border-ink/15 px-3 py-1.5 text-xs font-semibold hover:bg-cream\">Transfer stuck? Request refund</button>\n                        </form>\n                      )}\n                    </div>\n                  )}\n                </li>\n              );\n            })}\n          </ul>\n        </section>\n      )}\n\n      <section className=\"rounded-2xl border border-ink/10 bg-white p-5 shadow-sm shadow-ink/5\">\n        <h2 className=\"text-lg font-bold\">Activity</h2>\n        {entries.length === 0 ? (\n          <p className=\"mt-2 text-sm text-muted\">Nothing yet. Add money to get started.</p>\n        ) : (\n          <ul className=\"mt-3 divide-y divide-ink/10\">\n            {entries.map((e) => {\n              const credit = e.amountNgn > 0;\n              const Icon = e.type === \"TASK_FUND\" ? Lock : credit ? ArrowDownLeft : ArrowUpRight;\n              return (\n                <li key={e.id} className=\"flex items-center justify-between gap-3 py-3 text-sm\">\n                  <span className=\"flex min-w-0 items-center gap-3\">\n                    <span className=\"flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-cream\">\n                      <Icon className=\"h-4 w-4 text-forest\" aria-hidden />\n                    </span>\n                    <span className=\"min-w-0\">\n                      <span className=\"block font-semibold\">{LABEL[e.type] ?? e.type}</span>\n                      <span className=\"block truncate text-xs text-muted\">\n                        {e.note ? e.note + \" · \" : \"\"}\n                        {e.createdAt.toLocaleDateString(\"en-NG\")}\n                      </span>\n                    </span>\n                  </span>\n                  <span className={`shrink-0 font-bold ${credit ? \"text-emerald-700\" : \"text-ink\"}`}>\n                    {credit ? \"+\" : \"-\"}{naira(Math.abs(e.amountNgn))}\n                  </span>\n                </li>\n              );\n            })}\n          </ul>\n        )}\n      </section>\n    </main>\n  );\n}\n","src/app/admin/roqqu/page.tsx":"import { Suspense } from \"react\";\nimport { notFound } from \"next/navigation\";\nimport { Activity, Wallet, ArrowDownLeft, ArrowUpRight, RotateCcw, Radio, Coins, Percent, Users, Landmark } from \"lucide-react\";\nimport { db } from \"@/lib/db\";\nimport { getUserId } from \"@/lib/session\";\nimport { isLiveMode, isProdKey, roqquRequest, asRecord } from \"@/lib/payments/client\";\nimport { getNgnPerUsdt } from \"@/lib/payments/rates\";\nimport { withdrawalFeePercent } from \"@/lib/platform-fee\";\n\nconst naira = (n: number) => \"₦\" + n.toLocaleString(\"en-NG\");\n\nexport default function RoqquAdminPage() {\n  return (\n    <Suspense fallback={<div className=\"p-10 text-sm text-muted\">Loading...</div>}>\n      <Inner />\n    </Suspense>\n  );\n}\n\n// Only the emails in ADMIN_EMAILS (comma separated) can open this page.\nasync function Inner() {\n  const userId = await getUserId();\n  const admins = (process.env.ADMIN_EMAILS ?? \"\").split(\",\").map((e) => e.trim().toLowerCase()).filter(Boolean);\n  const me = userId ? await db.user.findUnique({ where: { id: userId }, select: { email: true } }) : null;\n  if (!me || !admins.includes(me.email.toLowerCase())) notFound();\n\n  const [addrRows, legacyOnly, deps, ledger, wds, byKind, lastEvent, recent, rate, wdRows] = await Promise.all([\n    db.depositAddress.groupBy({ by: [\"sandbox\"], _count: true }),\n    db.user.count({ where: { depositAddress: { not: null }, addresses: { none: {} } } }),\n    db.deposit.groupBy({ by: [\"status\"], _count: true, _sum: { amountNgn: true } }),\n    db.ledgerEntry.groupBy({ by: [\"type\"], _count: true, _sum: { amountNgn: true } }),\n    db.withdrawal.groupBy({ by: [\"status\"], _count: true, _sum: { amountNgn: true } }),\n    db.roqquTx.groupBy({ by: [\"kind\", \"live\"], _count: true, _sum: { amountNgn: true } }),\n    db.webhookEvent.findFirst({ where: { type: { startsWith: \"roqqu_\" } }, orderBy: { processedAt: \"desc\" } }),\n    db.roqquTx.findMany({ orderBy: { createdAt: \"desc\" }, take: 12 }),\n    getNgnPerUsdt(),\n    db.withdrawal.findMany({ select: { amountNgn: true, feeNgn: true, status: true, txHash: true, createdAt: true } }),\n  ]);\n\n  // Roqqu's own numbers for our account, only when live.\n  let stats: Record<string, unknown> | null = null;\n  if (isLiveMode()) {\n    try {\n      stats = asRecord(await roqquRequest(\"GET\", \"/analytics/stats\", { timeoutMs: 8000 }));\n    } catch {\n      stats = null;\n    }\n  }\n\n  const real = addrRows.filter((r) => !r.sandbox).reduce((a, r) => a + r._count, 0);\n  const sim = addrRows.filter((r) => r.sandbox).reduce((a, r) => a + r._count, 0) + legacyOnly;\n  const dep = (s: string) => deps.find((d) => d.status === s);\n  const led = (t: string) => ledger.find((l) => l.type === t);\n  const wd = (s: string) => wds.find((w) => w.status === s);\n  const kind = (k: string, live: boolean) => byKind.find((b) => b.kind === k && b.live === live);\n  // Revenue: TrustLoop keeps a percentage of every withdrawal. A fee counts as earned once the transfer is sent.\n  type W = (typeof wdRows)[number];\n  const sumBy = (rows: W[], f: (w: W) => number) => rows.reduce((a, w) => a + f(w), 0);\n  const demo = (w: W) => !w.txHash || w.txHash.startsWith(\"mock_\"); // sandbox transfers move no real money\n  const sent = wdRows.filter((w) => w.status === \"COMPLETED\");\n  const feesReal = sumBy(sent.filter((w) => !demo(w)), (w) => w.feeNgn);\n  const feesDemo = sumBy(sent.filter(demo), (w) => w.feeNgn);\n  const feesAll = feesReal + feesDemo;\n  const feesPending = sumBy(wdRows.filter((w) => [\"PENDING\", \"PROCESSING\", \"REFUND_REQUESTED\"].includes(w.status)), (w) => w.feeNgn);\n  const grossSent = sumBy(sent, (w) => w.amountNgn);\n  const netSent = grossSent - feesAll;\n  const payouts = led(\"TASK_PAYOUT\")?._sum.amountNgn ?? 0;\n  const funded = -(led(\"TASK_FUND\")?._sum.amountNgn ?? 0);\n  const held = ledger.reduce((a, l) => a + (l._sum.amountNgn ?? 0), 0);\n  const pct = (a: number, b: number) => (b > 0 ? `${((a / b) * 100).toFixed(1)}%` : \"-\");\n  const day = (d: Date) => d.toLocaleDateString(\"en-CA\", { timeZone: \"Africa/Lagos\" });\n  const days = Array.from({ length: 14 }, (_, i) => day(new Date(Date.now() - (13 - i) * 86_400_000)));\n  const byDay = days.map((d) => ({ d, fee: sumBy(sent.filter((w) => day(w.createdAt) === d), (w) => w.feeNgn) }));\n  const maxDay = Math.max(1, ...byDay.map((x) => x.fee));\n  const mode = isLiveMode() ? (isProdKey() ? \"Live\" : \"Roqqu test environment\") : \"Simulator\";\n\n  const tiles: [string, string, string, typeof Wallet][] = [\n    [\"Wallet addresses made\", String(real + sim), `${real} on Roqqu, ${sim} simulated`, Wallet],\n    [\"Top-ups confirmed\", String(dep(\"CONFIRMED\")?._count ?? 0), naira(dep(\"CONFIRMED\")?._sum.amountNgn ?? 0), ArrowDownLeft],\n    [\"Paid to freelancers\", String(led(\"TASK_PAYOUT\")?._count ?? 0), naira(led(\"TASK_PAYOUT\")?._sum.amountNgn ?? 0), Activity],\n    [\"Withdrawals sent\", String(wd(\"COMPLETED\")?._count ?? 0), naira(wd(\"COMPLETED\")?._sum.amountNgn ?? 0), ArrowUpRight],\n    [\"Withdrawals in progress\", String((wd(\"PROCESSING\")?._count ?? 0) + (wd(\"REFUND_REQUESTED\")?._count ?? 0)), \"Waiting on Roqqu\", Radio],\n    [\"Returned to wallets\", String((wd(\"FAILED\")?._count ?? 0)), naira(wd(\"FAILED\")?._sum.amountNgn ?? 0), RotateCcw],\n  ];\n\n  return (\n    <main className=\"mx-auto max-w-4xl space-y-5 px-5 py-6\">\n      <header>\n        <h1 className=\"text-2xl font-extrabold\">Roqqu activity</h1>\n        <p className=\"mt-1 text-sm text-muted\">\n          Counts come from TrustLoop's own records of every Roqqu call and webhook. Mode: <b>{mode}</b>. Price of 1 USDT: <b>{naira(Math.round(rate.rate))}</b> ({rate.source === \"roqqu\" ? \"live from Roqqu\" : \"fixed\"}).\n        </p>\n        <p className=\"mt-1 text-sm text-muted\">\n          Last Roqqu webhook received: <b>{lastEvent ? lastEvent.processedAt.toLocaleString(\"en-NG\") : \"none yet\"}</b>\n        </p>\n      </header>\n\n      <section className=\"rounded-2xl border border-forest/20 bg-white p-5 shadow-sm shadow-ink/5\">\n        <h2 className=\"flex items-center gap-2 text-lg font-bold\"><Coins className=\"h-5 w-5 text-forest\" aria-hidden /> How TrustLoop makes money</h2>\n        <p className=\"mt-1 text-sm text-muted\">\n          Joining, posting, applying and earning are free. TrustLoop keeps <b className=\"text-ink\">{withdrawalFeePercent()}%</b> of every withdrawal, shown to the user before they confirm. The fee is the part of the withdrawal that is not sent out.\n        </p>\n        <div className=\"mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4\">\n          {([\n            [\"Revenue earned\", naira(feesReal), feesDemo ? `plus ${naira(feesDemo)} from sandbox transfers` : \"settled through Roqqu\", Landmark],\n            [\"Pending fees\", naira(feesPending), \"transfers still in progress\", Radio],\n            [\"Average fee\", sent.length ? naira(Math.round(feesAll / sent.length)) : \"-\", `per withdrawal, ${sent.length} sent`, Percent],\n            [\"Share of earnings\", pct(feesAll, payouts), \"fees as part of what freelancers earned\", Users],\n          ] as [string, string, string, typeof Wallet][]).map(([label, big, small, Icon]) => (\n            <div key={label} className=\"rounded-xl bg-cream/60 p-4\">\n              <Icon className=\"h-4 w-4 text-forest\" aria-hidden />\n              <p className=\"mt-1 text-xl font-extrabold\">{big}</p>\n              <p className=\"text-sm font-semibold\">{label}</p>\n              <p className=\"text-xs text-muted\">{small}</p>\n            </div>\n          ))}\n        </div>\n        {feesDemo > 0 && (\n          <p className=\"mt-3 rounded-lg bg-amber-50 px-3 py-2 text-xs font-semibold text-amber-800\">\n            Some figures come from sandbox transfers: no real money moved. Revenue earned counts only transfers confirmed through Roqqu.\n          </p>\n        )}\n\n        <h3 className=\"mt-5 text-sm font-bold\">Where the money goes</h3>\n        <table className=\"mt-2 w-full text-left text-sm\">\n          <tbody className=\"divide-y divide-ink/10\">\n            <tr><td className=\"py-2\">Hirers put into jobs</td><td className=\"text-right font-bold\">{naira(funded)}</td></tr>\n            <tr><td className=\"py-2\">Freelancers earned from jobs</td><td className=\"text-right font-bold\">{naira(payouts)}</td></tr>\n            <tr><td className=\"py-2\">Freelancers withdrew (before fee)</td><td className=\"text-right font-bold\">{naira(grossSent)}</td></tr>\n            <tr><td className=\"py-2 pl-4 text-muted\">of which paid out to freelancers</td><td className=\"text-right font-bold\">{naira(netSent)} <span className=\"font-normal text-muted\">({pct(netSent, grossSent)})</span></td></tr>\n            <tr><td className=\"py-2 pl-4 text-muted\">of which kept by TrustLoop</td><td className=\"text-right font-bold text-forest\">{naira(feesAll)} <span className=\"font-normal text-muted\">({pct(feesAll, grossSent)})</span></td></tr>\n            <tr><td className=\"py-2\">Still held in user wallets</td><td className=\"text-right font-bold\">{naira(held)}</td></tr>\n          </tbody>\n        </table>\n\n        <h3 className=\"mt-5 text-sm font-bold\">Fees earned, last 14 days</h3>\n        <ul className=\"mt-2 space-y-1.5\">\n          {byDay.map((x) => (\n            <li key={x.d} className=\"flex items-center gap-3 text-xs\">\n              <span className=\"w-12 shrink-0 text-muted\">{x.d.slice(5)}</span>\n              <span className=\"h-3 flex-1 overflow-hidden rounded-full bg-cream\">\n                <span className=\"block h-full rounded-full bg-forest\" style={{ width: `${(x.fee / maxDay) * 100}%` }} />\n              </span>\n              <span className=\"w-16 shrink-0 text-right font-semibold\">{naira(x.fee)}</span>\n            </li>\n          ))}\n        </ul>\n      </section>\n\n      <div className=\"grid grid-cols-2 gap-3 sm:grid-cols-3\">\n        {tiles.map(([label, big, small, Icon]) => (\n          <div key={label} className=\"rounded-2xl border border-ink/10 bg-white p-4 shadow-sm shadow-ink/5\">\n            <Icon className=\"h-5 w-5 text-forest\" aria-hidden />\n            <p className=\"mt-2 text-2xl font-extrabold\">{big}</p>\n            <p className=\"text-sm font-semibold\">{label}</p>\n            <p className=\"text-xs text-muted\">{small}</p>\n          </div>\n        ))}\n      </div>\n\n      <section className=\"rounded-2xl border border-ink/10 bg-white p-5 shadow-sm shadow-ink/5\">\n        <h2 className=\"text-lg font-bold\">Confirmed by Roqqu webhooks</h2>\n        <table className=\"mt-3 w-full text-left text-sm\">\n          <thead className=\"text-xs uppercase text-muted\"><tr><th className=\"py-1\">Event</th><th>Live</th><th>Test or simulated</th></tr></thead>\n          <tbody className=\"divide-y divide-ink/10\">\n            {[\n              [\"PAYMENT_LINK\", \"Payment links paid\"],\n              [\"CHAIN_DEPOSIT\", \"USDT sent to user addresses\"],\n              [\"SEND\", \"Withdrawals sent on-chain\"],\n              [\"REFUND\", \"Failed sends refunded\"],\n            ].map(([k, label]) => (\n              <tr key={k}>\n                <td className=\"py-2 font-semibold\">{label}</td>\n                <td>{kind(k, true)?._count ?? 0}</td>\n                <td>{kind(k, false)?._count ?? 0}</td>\n              </tr>\n            ))}\n          </tbody>\n        </table>\n      </section>\n\n      {stats && (\n        <section className=\"rounded-2xl border border-ink/10 bg-white p-5 shadow-sm shadow-ink/5\">\n          <h2 className=\"text-lg font-bold\">Roqqu's own numbers for TrustLoop</h2>\n          <dl className=\"mt-3 grid grid-cols-3 gap-3 text-sm\">\n            {([\"total_volume\", \"total_credit\", \"total_debit\"] as const).map((k) => (\n              <div key={k}>\n                <dt className=\"text-muted\">{k.replace(\"total_\", \"Total \")}</dt>\n                <dd className=\"text-xl font-extrabold\">{String(stats?.[k] ?? \"-\")}</dd>\n              </div>\n            ))}\n          </dl>\n        </section>\n      )}\n\n      <section className=\"rounded-2xl border border-ink/10 bg-white p-5 shadow-sm shadow-ink/5\">\n        <h2 className=\"text-lg font-bold\">Latest events</h2>\n        {recent.length === 0 ? (\n          <p className=\"mt-2 text-sm text-muted\">No Roqqu events yet.</p>\n        ) : (\n          <ul className=\"mt-3 divide-y divide-ink/10 text-sm\">\n            {recent.map((r) => (\n              <li key={r.id} className=\"flex flex-wrap items-center justify-between gap-2 py-2\">\n                <span><b>{r.kind.replace(\"_\", \" \").toLowerCase()}</b> · {r.status.toLowerCase()}{r.network ? ` · ${r.network}` : \"\"}</span>\n                <span className=\"text-xs text-muted\">{r.live ? \"live\" : \"test\"} · {r.createdAt.toLocaleString(\"en-NG\")}</span>\n              </li>\n            ))}\n          </ul>\n        )}\n      </section>\n    </main>\n  );\n}\n"};
// TrustLoop: revenue model installer (withdrawal fee, fee-aware withdraw form, admin revenue). Safe to run twice.
const fs = require("fs");
const path = require("path");
const root = process.cwd();
if (!fs.existsSync(path.join(root, "prisma", "schema.prisma")) || !fs.existsSync(path.join(root, "src"))) {
  console.error("Run this from your trustloop project folder (the one that has prisma and src).");
  process.exit(1);
}
const backupDir = path.join(root, ".roqqu-backup");
const done = [], warn = [];

const readN = (p) => { const raw = fs.readFileSync(p, "utf8"); return { text: raw.replace(/\r\n/g, "\n"), crlf: raw.includes("\r\n") }; };
const writeN = (p, text, crlf) => fs.writeFileSync(p, crlf ? text.replace(/\n/g, "\r\n") : text);

// 1. Write files (backing up any that already exist).
for (const [rel, content] of Object.entries(FILES)) {
  const abs = path.join(root, rel);
  fs.mkdirSync(path.dirname(abs), { recursive: true });
  if (fs.existsSync(abs)) {
    const cur = fs.readFileSync(abs, "utf8").replace(/\r\n/g, "\n");
    if (cur === content) { continue; }
    const b = path.join(backupDir, rel);
    fs.mkdirSync(path.dirname(b), { recursive: true });
    if (!fs.existsSync(b)) fs.copyFileSync(abs, b);
  }
  fs.writeFileSync(abs, content);
  done.push("wrote " + rel);
}

// 2. Small edits to existing files. Each one checks that its anchor exists exactly once.
function patch(rel, label, edits, optional) {
  const abs = path.join(root, rel);
  if (!fs.existsSync(abs)) { if (!optional) warn.push(`${label}: ${rel} not found`); return false; }
  let { text, crlf } = readN(abs);
  const orig = text;
  for (const e of edits) {
    if (e.skipIf && text.includes(e.skipIf)) continue;
    const count = text.split(e.find).length - 1;
    if (count !== 1) { warn.push(`${label}: could not find the spot to edit in ${rel} (${e.what})`); return false; }
    text = text.replace(e.find, () => e.replace);
  }
  if (text !== orig) {
    const b = path.join(backupDir, rel);
    fs.mkdirSync(path.dirname(b), { recursive: true });
    if (!fs.existsSync(b)) fs.copyFileSync(abs, b);
    writeN(abs, text, crlf);
    done.push("edited " + rel);
  }
  return true;
}

// Prisma schema: add fields to existing models, and two new models.
(function schema() {
  const rel = "prisma/schema.prisma";
  const abs = path.join(root, rel);
  let { text, crlf } = readN(abs);
  const orig = text;
  const addFields = (model, fields) => {
    const re = new RegExp(`(model ${model} \\{[\\s\\S]*?)(\\n\\})`);
    const m = text.match(re);
    if (!m) { warn.push(`schema: model ${model} not found`); return; }
    const body = m[1];
    const missing = fields.filter((f) => !new RegExp(`^\\s*${f.split(/\s+/)[0]}\\s`, "m").test(body));
    if (!missing.length) return;
    text = text.replace(re, (_, a, b) => a + "\n" + missing.map((f) => "  " + f).join("\n") + b);
  };
  addFields("Deposit", ["txHash String?", "network String?", "token String?"]);
  addFields("Withdrawal", ["refid String?", "feeNgn Int @default(0)", "feePercent Float @default(0)"]);
  addFields("User", ["roqquStatus String?", "roqquCheckedAt DateTime?", "addresses DepositAddress[]"]);
  if (!text.includes("model DepositAddress")) {
    text += `
model DepositAddress {
  id        String   @id @default(cuid())
  user      User     @relation(fields: [userId], references: [id])
  userId    String
  network   String
  address   String
  sandbox   Boolean  @default(false)
  createdAt DateTime @default(now())

  @@unique([userId, network])
  @@index([address])
}
`;
  }
  if (!text.includes("model RoqquTx")) {
    text += `
model RoqquTx {
  id        String   @id @default(cuid())
  kind      String
  live      Boolean  @default(false)
  userId    String?
  reference String?
  hash      String?
  token     String?
  network   String?
  value     Float?
  amountNgn Int?
  status    String
  note      String?
  createdAt DateTime @default(now())

  @@index([kind, createdAt])
  @@index([hash])
}
`;
  }
  if (text !== orig) {
    const b = path.join(backupDir, rel);
    fs.mkdirSync(path.dirname(b), { recursive: true });
    if (!fs.existsSync(b)) fs.copyFileSync(abs, b);
    writeN(abs, text, crlf);
    done.push("edited " + rel);
  }
})();

// Landing page: say plainly that joining is free and withdrawing has a small fee.
patch("src/app/page.tsx", "landing page", [
  { what: "freelancer list", skipIf: "Free to join", find: `"Build a profile of proven work anyone can verify"]`, replace: `"Build a profile of proven work anyone can verify", "Free to join. A small fee applies only when you withdraw, and we show it first"]` },
]);

// Keep backups out of git.
try {
  const gi = path.join(root, ".gitignore");
  const cur = fs.existsSync(gi) ? fs.readFileSync(gi, "utf8") : "";
  if (!cur.includes(".roqqu-backup")) fs.appendFileSync(gi, (cur.endsWith("\n") || !cur ? "" : "\n") + ".roqqu-backup/\n");
} catch {}

console.log("\n" + done.map((d) => "  " + d).join("\n"));
if (warn.length) console.log("\nNeeds a look:\n" + warn.map((w) => "  - " + w).join("\n"));
console.log("\nInstalled. Next: npx prisma migrate dev --name withdrawal_fee   then   npx prisma generate");
